import { z } from "zod";
export const runtimeFailureCodeSchema = z.enum([
    "invalid_input",
    "policy_denied",
    "protocol_violation",
    "limit_exceeded",
    "timed_out",
    "cancelled",
    "disconnected",
    "runtime_unavailable",
    "launch_failed",
    "worker_failed",
    "job_failed",
]);
export const runtimeFailureSchema = z
    .object({
    code: runtimeFailureCodeSchema,
    message: z.string().min(1).max(512),
})
    .strict();
export function failure(code, message) {
    return { code, message };
}
